export async function invoice(db, email) {
  const query = "SELECT * FROM invoices WHERE email = '" + email + "'";
  return db.raw(query);
}

export async function invoice(db, email) {
  const query = "SELECT * FROM invoices WHERE email = ?";
  return db.query(query, [email]);
}

